print(not True and False) #This is False because not True is False. And False and False is False.
print(True or False and False) #This is True. And is evaluated first so False. So it's True or False. Since True is first, it is True.
print(not (5 > 3)) #This is False. 5 is greater than 3, True; not True is False.
print(10 == 10 and 4 != 4) #This is False. 10==10 is True; 4!=4 is False. Both criteria not met, so False.
print(not False or not True) #This is True. not False = True; not True = False so either True or False. Since one side is True, it's true.